real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0f;
    const size_t n = (size_t)LEN_1D;
    const size_t total = (size_t)iterations * n;

    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0f;
        size_t i = 0;

        while (i < n) {
            size_t vl = __riscv_vsetvl_e32m1(n - i);
            vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float*)(x + i), vl);
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
            vfloat32m1_t vsum = __riscv_vfredosum_vs_f32m1_f32m1(vx, vzero, vl);
            s += __riscv_vfmv_f_s_f32m1_f32(vsum);
            i += vl;
        }

        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }

    y[0] = acc / (real_t)(total);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

