{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t half = 0.5f, ptiny = 1.0e-2f;
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t xi  = half * ( apps_x1[i]  + apps_x2[i]  - apps_x3[i]  - apps_x4[i]  );
            real_t xj  = half * ( apps_x2[i]  + apps_x3[i]  - apps_x4[i]  - apps_x1[i]  );
            real_t yi  = half * ( apps_y1[i]  + apps_y2[i]  - apps_y3[i]  - apps_y4[i]  );
            real_t yj  = half * ( apps_y2[i]  + apps_y3[i]  - apps_y4[i]  - apps_y1[i]  );
            real_t fxi = half * ( apps_fx1[i] + apps_fx2[i] - apps_fx3[i] - apps_fx4[i] );
            real_t fxj = half * ( apps_fx2[i] + apps_fx3[i] - apps_fx4[i] - apps_fx1[i] );
