            vfloat32m1_t pmin_vec = __riscv_vfmv_v_f_f32m1(pmin, vl);
            vfloat32m1_t eosvmax_vec = __riscv_vfmv_v_f_f32m1(eosvmax, vl);
            vfloat32m1_t vnewc = __riscv_vle32_v_f32m1(&apps_vnewc[i], vl);

            vbool32_t mask1 = __riscv_vmflt_vv_f32m1_b32(p, p_cut_vec, vl);
            vbool32_t mask2 = __riscv_vmfge_vv_f32m1_b32(vnewc, eosvmax_vec, vl);
